interface.definition:
interface UseExpensesReturn {
  expenses: ExpenseEntry[];
  isLoading: boolean;
  addExpense: (expense: Omit<ExpenseEntry, 'id' | 'createdAt'>) => Promise<Result<number>>;
  updateExpense: (id: number, updates: Partial<ExpenseEntry>) => Promise<Result<void>>;
  deleteExpense: (id: number) => Promise<Result<void>>;
  totalMonthlyExpenses: string;
  expensesByCategory: Map<ExpenseCategory, string>;
}

z.object({
  category: z.enum(['housing', 'transport', 'food', 'utilities', 'insurance', 'entertainment', 'other']),
  amount: z.string().min(1).refine(val => !isNaN(parseFloat(val)) && parseFloat(val) >= 0),
  description: z.string().optional()
})
